-- Legado: Movimiento -> requests (~700 registros)
-- Columnas origen: NroDocumento, IdDoctor, Destino, Autorizado, FECHA
-- PRERREQUISITO: 01_proveedores_legado.sql debe estar aplicado

DO $$ DECLARE v_admin UUID; BEGIN
  SELECT id INTO v_admin FROM users WHERE username = 'admin' LIMIT 1;
  IF v_admin IS NULL THEN RAISE EXCEPTION 'Usuario admin no encontrado. Ejecuta primero los seeds de usuarios.'; END IF;

END $$;

-- Avanzar secuencia de folios mas alla del historico
SELECT setval('folio_seq', GREATEST((SELECT COALESCE(MAX(folio),703) FROM requests), 703) + 1);
